

CREATE TABLE `EUROLEAGUE_GAMES` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `SEASON` int NOT NULL,
  `GAMEWEEK` int NOT NULL,
  `GAMEWEEK_LEAGUE` int NOT NULL,
  `PLAYER_HOME` int NOT NULL,
  `PLAYER_AWAY` int NOT NULL,
  `GOALS_HOME` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `GOALS_AWAY` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `POINTS_HOME` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `POINTS_AWAY` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=903 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `EUROLEAGUE_TABLE` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `SEASON` int NOT NULL,
  `POSITION` int NOT NULL,
  `PLAYER_ID` int NOT NULL,
  `WINS` varchar(2) COLLATE utf8mb3_unicode_ci NOT NULL,
  `DRAWS` varchar(2) COLLATE utf8mb3_unicode_ci NOT NULL,
  `LOST` varchar(2) COLLATE utf8mb3_unicode_ci NOT NULL,
  `GOALS_FAVOUR` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `GOALS_AGAINST` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `POINTS` varchar(6) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `PLAYED` int DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `GAMEWEEK_INFO` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `SEASON` int NOT NULL,
  `MONTH` varchar(100) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `GAMEWEEK` int NOT NULL,
  `player_id` int NOT NULL,
  `PLAYER_NAME` varchar(30) COLLATE utf8mb3_unicode_ci NOT NULL,
  `TEAM_VALUE` double NOT NULL,
  `TEAM_SALARY` float NOT NULL,
  `BALANCE` float NOT NULL,
  `PROPERTY` float NOT NULL,
  `GAMEWEEK_POSITION` int NOT NULL,
  `GAMEWEEK_POINTS` float NOT NULL,
  `POSITION_PRIZE` float DEFAULT NULL,
  `BEST_LINEUP` int DEFAULT NULL,
  `TV_RIGHTS` float NOT NULL DEFAULT '0',
  `MATCHTYPE` varchar(100) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `AUDIENCE` float NOT NULL DEFAULT '0',
  `EXTRA_PAYMENT` varchar(50) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `EXTRA_PAYMENT_VAL` float DEFAULT NULL,
  `CAPTAIN` varchar(20) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `CAPTAIN_POINTS` float DEFAULT NULL,
  `CAPTAIN_RATING` varchar(50) COLLATE utf8mb3_unicode_ci NOT NULL,
  `CAPTAIN_PRIZE` float DEFAULT NULL,
  `GAMEWEEK_POINTS_CUM` decimal(6,0) DEFAULT NULL,
  `CAPTAIN_POINTS_CUM` decimal(6,0) DEFAULT NULL,
  `TEAM_SALARY_CUM` float DEFAULT NULL,
  `POSITION_PRIZE_CUM` float DEFAULT NULL,
  `BEST_LINEUP_CUM` int DEFAULT NULL,
  `FUTMONDO_PRIZE_CUM` float DEFAULT NULL,
  `PAYMENTS_CUM` float DEFAULT NULL,
  `TOTAL_CUM` float DEFAULT NULL,
  `FUTMONDO_PRIZE` float DEFAULT NULL,
  `PAYMENT` float DEFAULT NULL,
  `TOTAL` float DEFAULT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=4338 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `KNOCKOUT_TABLE` (
  `ID` int unsigned NOT NULL,
  `SEASON` int NOT NULL,
  `TROPHY` varchar(10) COLLATE utf8mb3_unicode_ci NOT NULL,
  `JSON_STRING` varchar(2000) COLLATE utf8mb3_unicode_ci NOT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `PLAYERS_INFO` (
  `PLAYER_ID` int unsigned NOT NULL AUTO_INCREMENT,
  `PLAYER_NAME` varchar(30) COLLATE utf8mb3_unicode_ci NOT NULL,
  `PLAYER_DESC` varchar(1000) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `REPUTATION` float DEFAULT NULL,
  `REPUTATION_STADIUM` float DEFAULT NULL,
  `SPONSOR` int DEFAULT NULL,
  `TV_RIGHTS` int DEFAULT NULL,
  `LEAGUE` int DEFAULT NULL,
  `CHAMPIONS` int DEFAULT NULL,
  `UEFA` int DEFAULT NULL,
  `CUP` int DEFAULT NULL,
  `EUROPCUP` int DEFAULT NULL,
  `WORLDCUP` int DEFAULT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`PLAYER_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `SEASON_CALENDAR` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `SEASON` int NOT NULL,
  `GAMEWEEK` int NOT NULL,
  `DESCRIPTION` varchar(30) COLLATE utf8mb3_unicode_ci NOT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `EURO_GK` varchar(3) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=382 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `SPONSORS` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `ENTERPRISE` varchar(500) COLLATE utf8mb3_unicode_ci NOT NULL,
  `SRC_LOGO` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `UPFRONT_INCOME` float NOT NULL,
  `EXTRA` varchar(500) COLLATE utf8mb3_unicode_ci NOT NULL,
  `BONUS` varchar(200) COLLATE utf8mb3_unicode_ci NOT NULL,
  `FIXED_AMOUNT` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `VARIABLE_AMOUNT` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `STADIUM_INFO` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `PLAYER_ID` int NOT NULL,
  `STADIUM` varchar(50) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `REPUTATION` float NOT NULL,
  `PICTURE_SRC` varchar(50) COLLATE utf8mb3_unicode_ci NOT NULL,
