  `FIELD` varchar(60) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `STADIUM_STRUCTURE` varchar(60) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `PARKING` varchar(60) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `LIGHT` varchar(60) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `SCORE` varchar(60) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `NBR_STORE` int NOT NULL,
  `MARKETING_DIRECTOR` int NOT NULL,
  `TOTAL_INVESTMENT` float NOT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;




CREATE TABLE `TV_RIGHTS` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `CHANNEL` varchar(500) COLLATE utf8mb3_unicode_ci NOT NULL,
  `SRC_LOGO` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `DURATION` varchar(500) COLLATE utf8mb3_unicode_ci NOT NULL,
  `UPFRONT_INCOME` float NOT NULL,
  `BONUS` varchar(200) COLLATE utf8mb3_unicode_ci NOT NULL,
  `FIXED_AMOUNT` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `VARIABLE_AMOUNT` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `INSERT_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_DTM` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;


